private static function restAtLeastHalf(string $rest): bool
{
    if ($rest === '') {
        return false;
    }
    if ((int) $rest[0] > 5) {
        return true;
    }
    if ((int) $rest[0] < 5) {
        return false;
    }
    // ровно половина: если в остатке есть ненулевой знак
    for ($i = 1; $i < strlen($rest); $i++) {
        if ($rest[$i] !== '0') {
            return true;
        }
    }

    return true; // ровно половина -> "up"
}

